""" Script d'entrée unique pour lancer l'ingestion et l'application des corporate actions (équivalent à 'python -m corporate_actions run'). """ from corporate_actions.cli import _run_all, _build_parser import logging import sys
def main(): logging.basicConfig( level=logging.INFO, format="%(asctime)s %(levelname)-8s %(name)s -- %(message)s", ) parser = _build_parser() args = parser.parse_args() # Force la commande 'run' même si non précisée if not hasattr(args, 'command') or args.command != 'run': args.command = 'run' _run_all(args)
if __name__ == "__main__": main()

"""ihm/components/db_controls.py — Contrôles de connexion DB pour l'IHM.""" from __future__ import annotations
import streamlit as st
from ihm.services.db import ( clear_runtime_db_config, get_db_status, get_last_query_error, reset_db_caches, set_runtime_db_config, )
def render_db_connection_form(form_key: str, *, show_host_fields: bool = True) -> None: """Affiche un formulaire de connexion DB réutilisable.""" status = get_db_status() host = str(status.get("host") or "localhost") name = str(status.get("name") or "alpha_trade") user = str(status.get("user") or "") current_password = str(status.get("password") or "") source = str(status.get("source") or "inconnue") connected = bool(status.get("connected")) db_error = status.get("last_db_error")
if connected: st.success(f" Connecté à `{name}` sur `{host}` via `{source}`.") else: st.info("Cette partie de l'IHM dépend de la base MySQL Alpha Trade.") if db_error: st.warning(str(db_error))
with st.form(form_key, clear_on_submit=False): if show_host_fields: col1, col2 = st.columns(2) with col1: host_value = st.text_input("Hôte MySQL", value=host) with col2: name_value = st.text_input("Base de données", value=name) else: host_value = host name_value = name
col3, col4 = st.columns(2) with col3: user_value = st.text_input("Login DB", value=user) with col4: password_value = st.text_input("Mot de passe DB", value="", type="password") st.caption("Laissez le mot de passe vide pour conserver la valeur déjà active si nécessaire.")
action_col1, action_col2, action_col3 = st.columns(3) connect_clicked = action_col1.form_submit_button("Tester / connecter", use_container_width=True) env_clicked = action_col2.form_submit_button("Utiliser ENV", use_container_width=True) refresh_clicked = action_col3.form_submit_button("Rafraîchir", use_container_width=True)
if connect_clicked: set_runtime_db_config( host=host_value, name=name_value, user=user_value, password=password_value or current_password, ) st.rerun()
if env_clicked: clear_runtime_db_config() st.rerun()
if refresh_clicked: reset_db_caches(clear_errors=False) st.rerun()
def render_db_unavailable(page_label: str, *, form_key: str) -> None: """Affiche un message explicite si une page nécessite la DB.""" st.warning(f"La page **{page_label}** nécessite une connexion à la base Alpha Trade.") render_db_connection_form(form_key=form_key)
def render_query_diagnostic(empty_message: str) -> bool: """Affiche soit le diagnostic SQL, soit un message de vide métier.
Retourne True si un message a été affiché à la place d'un tableau. """ query_error = get_last_query_error() if query_error: st.warning(query_error) return True st.info(empty_message) return True

"""ihm/components/db_controls.py — Contrôles de connexion DB pour l'IHM.""" from __future__ import annotations
import streamlit as st
from ihm.services.db import ( clear_runtime_db_config, get_db_status, get_last_query_error, reset_db_caches, set_runtime_db_config, )
def render_db_connection_form(form_key: str, *, show_host_fields: bool = True) -> None: """Affiche un formulaire de connexion DB réutilisable.""" status = get_db_status() host = str(status.get("host") or "localhost") name = str(status.get("name") or "alpha_trade") user = str(status.get("user") or "") current_password = str(status.get("password") or "") source = str(status.get("source") or "inconnue") connected = bool(status.get("connected")) db_error = status.get("last_db_error")
if connected: st.success(f" Connecté à `{name}` sur `{host}` via `{source}`.") else: st.info("Cette partie de l'IHM dépend de la base MySQL Alpha Trade.") if db_error: st.warning(str(db_error))
with st.form(form_key, clear_on_submit=False): if show_host_fields: col1, col2 = st.columns(2) with col1: host_value = st.text_input("Hôte MySQL", value=host) with col2: name_value = st.text_input("Base de données", value=name) else: host_value = host name_value = name
col3, col4 = st.columns(2) with col3: user_value = st.text_input("Login DB", value=user) with col4: password_value = st.text_input("Mot de passe DB", value="", type="password") st.caption("Laissez le mot de passe vide pour conserver la valeur déjà active si nécessaire.")
action_col1, action_col2, action_col3 = st.columns(3) connect_clicked = action_col1.form_submit_button("Tester / connecter", width="stretch") env_clicked = action_col2.form_submit_button("Utiliser ENV", width="stretch") refresh_clicked = action_col3.form_submit_button("Rafraîchir", width="stretch")
if connect_clicked: set_runtime_db_config( host=host_value, name=name_value, user=user_value, password=password_value or current_password, ) st.rerun()
if env_clicked: clear_runtime_db_config() st.rerun()
if refresh_clicked: reset_db_caches(clear_errors=False) st.rerun()
def render_db_unavailable(page_label: str, *, form_key: str) -> None: """Affiche un message explicite si une page nécessite la DB.""" st.warning(f"La page **{page_label}** nécessite une connexion à la base Alpha Trade.") render_db_connection_form(form_key=form_key)
def render_query_diagnostic(empty_message: str) -> bool: """Affiche soit le diagnostic SQL, soit un message de vide métier.
Retourne True si un message a été affiché à la place d'un tableau. """ query_error = get_last_query_error() if query_error: st.warning(query_error) return True st.info(empty_message) return True

"""ihm/pages/pipeline.py — Vue séquentielle du pipeline métier.""" from __future__ import annotations
import streamlit as st
PIPELINE_STEPS = [ { "num": "1", "name": "Import Alpaca Bar", "desc": "Ingestion des barres OHLCV journalières depuis Alpaca Market Data.", "tables": "stock_bars", "cli": "python -m dataIntegrityEngine.import_alpaca_bar", "deps": "—", }, { "num": "1a", "name": "Corporate Actions Sync", "desc": "Ingestion des dividendes/splits depuis Alpaca (référentiel). Se fait AVANT le sanitizer.", "tables": "corporate_actions_events", "cli": "python -m corporate_actions sync --skip-existing", "deps": "import_alpaca_bar", }, { "num": "2", "name": "Data Sanitizer Daily", "desc": "Nettoyage, alignement calendrier, détection d'anomalies sur les barres brutes.", "tables": "stock_bars_daily, cleaning_audit_log", "cli": "python -m dataIntegrityEngine.data_sanitizer_daily", "deps": "import_alpaca_bar, corporate_actions sync", }, { "num": "3", "name": "Stock Screener", "desc": "Scores de base : liquidité 30j, force relative 6m vs SPY, range 10 ans.", "tables": "stock_scores", "cli": "python -m dataIntegrityEngine.stock_screener", "deps": "data_sanitizer_daily", }, { "num": "4", "name": "Alpha Scanner", "desc": "Scoring avancé Minervini/VCP + neutralisation sectorielle + sélection Top N.", "tables": "stock_scores (update)", "cli": "python -m selector.alpha_scanner", "deps": "stock_screener", }, { "num": "5", "name": "Sentiment Pipeline", "desc": "Ingestion news → scoring FinBERT → features ticker/secteur journalières.", "tables": "ticker_daily_sentiment_features, sector_daily_sentiment_features", "cli": "python -m event_sentiment", "deps": "alpha_scanner", }, { "num": "6", "name": "Signal Aggregator", "desc": "Fusion quant (75%) + sentiment ticker (15%) + macro sectoriel (10%) → final_score_sentiment.", "tables": "stock_scores (update final_score_sentiment)", "cli": "python -m event_sentiment.signal_aggregator", "deps": "sentiment_pipeline", }, { "num": "7", "name": "Risk Management", "desc": "Sizing ATR/Kelly, contraintes portefeuille, circuit breaker → portefeuille cible.", "tables": "risk_decisions, portfolio_targets", "cli": "python -m risk_management.run_risk --account-equity 100000", "deps": "signal_aggregator", }, { "num": "8", "name": "Execution", "desc": "Soumission ordres Alpaca (market/limit), bracket synthétique TP+TS, réconciliation, TCA.", "tables": "execution_runs, execution_orders, execution_fills, execution_events, broker_positions_snapshots", "cli": "python run_execution.py simulate # ou paper / live", "deps": "run_risk", }, { "num": "8a", "name": "Corporate Actions Apply", "desc": "Application des dividendes/splits sur les positions existantes. Se fait APRÈS l'exécution.", "tables": "corporate_actions_applications, portfolio_cash_ledger", "cli": "python -m corporate_actions apply", "deps": "run_execution", }, ]
def render() -> None: st.header(" Pipeline Quotidien") st.caption("Ordre d'exécution strict — chaque étape dépend de la précédente.")
for step in PIPELINE_STEPS: with st.expander(f"**{step['num']}. {step['name']}**", expanded=False): st.markdown(f"**Description** : {step['desc']}") st.markdown(f"**Tables impactées** : `{step['tables']}`") st.markdown(f"**Dépendances** : {step['deps']}") st.code(step["cli"], language="powershell")
